fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as stated in the problem):
    // start + sub.len() <= main.len()
    let sub_len = sub.len();
    for j in 0..sub_len {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty subarray always matches.
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    let max_start = main.len() - sub.len();
    for start in 0..=max_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}